const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mayfield = ee.Geometry.Point([-88.6439, 36.7412]); // Approx. center of Mayfield, Kentucky
  const scale = 1000; // Resolution for reduction in meters

  // Period 1: November 2021
  const startDate1 = '2021-11-01';
  const endDate1 = '2021-11-30';

  // Period 2: December 10-12, 2021
  const startDate2 = '2021-12-10';
  const endDate2 = '2021-12-12';

  // 2. Data Acquisition & Check
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG'); // Daily VIIRS DNB
  const bandName = 'avg_rad'; // Average Radiance

  // Filter for Period 1 (November 2021)
  const collection1 = viirs.filterDate(startDate1, endDate1).filterBounds(mayfield);
  const size1 = await collection1.size().getInfo();

  if (size1 === 0) {
    console.log(`No VIIRS DNB images found for November 2021 (${startDate1} to ${endDate1}).`);
    console.log("C1");
    return;
  }

  // Filter for Period 2 (December 10-12, 2021)
  const collection2 = viirs.filterDate(startDate2, endDate2).filterBounds(mayfield);
  const size2 = await collection2.size().getInfo();

  if (size2 === 0) {
    console.log(`No VIIRS DNB images found for December 10-12, 2021 (${startDate2} to ${endDate2}).`);
    console.log("C1");
    return;
  }

  // 3. Processing (Calculate pixel count to detect C2)
  // Calculate the mean image for each period
  const meanImage1 = collection1.select(bandName).mean();
  const meanImage2 = collection2.select(bandName).mean();

  // Reduce region to get the mean brightness and pixel count
  const reductionParams = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: mayfield,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Specify CRS for consistency
  };

  const stats1 = await meanImage1.reduceRegion(reductionParams).getInfo();
  const stats2 = await meanImage2.reduceRegion(reductionParams).getInfo();

  const meanRad1 = stats1 ? stats1[bandName] : null;
  const pixelCount1 = stats1 ? stats1[bandName + '_count'] : 0;
  const meanRad2 = stats2 ? stats2[bandName] : null;
  const pixelCount2 = stats2 ? stats2[bandName + '_count'] : 0;

  if (pixelCount1 === 0) {
    console.log(`No valid pixels for November 2021 after processing. (Images: ${size1})`);
    console.log("C2");
    return;
  }
  if (pixelCount2 === 0) {
    console.log(`No valid pixels for Dec 10-12, 2021 after processing. (Images: ${size2})`);
    console.log("C2");
    return;
  }

  // 4. Calculation & 5. Validation & Final Answer
  if (meanRad1 === null || isNaN(meanRad1) || meanRad2 === null || isNaN(meanRad2)) {
    console.log("Calculation resulted in null or NaN for mean radiance.");
    console.log("C3");
    return;
  }

  console.log(`Nov 2021: Images: ${size1}, Avg Brightness: ${meanRad1.toFixed(4)}, Pixels: ${pixelCount1}`);
  console.log(`Dec 10-12, 2021: Images: ${size2}, Avg Brightness: ${meanRad2.toFixed(4)}, Pixels: ${pixelCount2}`);

  if (meanRad1 > meanRad2) {
    console.log("A"); // Yes, nighttime brightness was higher in November 2021
  } else {
    console.log("B"); // No, nighttime brightness was not higher in November 2021
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (error) {
    console.error("Earth Engine authentication or initialization failed:", error);
    console.log("D"); // Indicate a general error
  }
}

initEE();
